#include <cstddef>
#include <type_traits>

template <class T>
constexpr T MAX(T a, T b) {
    return a > b ? a : b;
}

template <class T>
constexpr T SQUARE(T x) {
    return x * x;
}

constexpr bool IS_EVEN(int n) {
    return n % 2 == 0;
}

template <class T>
constexpr T CLAMP(T value, T low, T high) {
    if (value < low) return low;
    if (value > high) return high;
    return value;
}

int evaluations = 0;

int counted(int value) {
    ++evaluations;
    return value;
}
